BEGIN;
INSERT INTO student(full_name,email,password_hash) VALUES ('G05 A4 probe','g05-a4-probe@example.invalid','non-login-test-marker') RETURNING student_id AS sid \gset
INSERT INTO vendor(vendor_name,email,password_hash) VALUES ('G05 A4 probe','g05-vendor-probe@example.invalid','non-login-test-marker') RETURNING vendor_id AS vid \gset
INSERT INTO menu_item(vendor_id,item_name,price) VALUES (:vid,'G05 A4 probe',10) RETURNING item_id AS iid \gset
INSERT INTO customer_order(student_id,vendor_id,pickup_time) VALUES (:sid,:vid,'23:59') RETURNING order_id AS oid \gset
INSERT INTO order_item(order_id,item_id,quantity,price_at_order) VALUES (:oid,:iid,2,10);
INSERT INTO queue_entry(order_id,queue_number,queue_date) VALUES (:oid,900001,'2099-01-01');
INSERT INTO notification(order_id,message) VALUES (:oid,'G05 A4 probe');
UPDATE vendor SET is_active=false WHERE vendor_id=:vid;
UPDATE menu_item SET price=12.5 WHERE item_id=:iid;
UPDATE customer_order SET status='preparing' WHERE order_id=:oid;
UPDATE queue_entry SET status='called' WHERE order_id=:oid;
UPDATE notification SET is_read=true WHERE order_id=:oid;
SELECT sum(quantity*price_at_order) AS probe_total FROM order_item WHERE order_id=:oid;
ROLLBACK;

BEGIN;
-- Run as a superuser or canteen_admin. Default ACLs apply only to objects
-- subsequently created by canteen_admin in public.
ALTER DEFAULT PRIVILEGES FOR ROLE canteen_admin IN SCHEMA public
    REVOKE ALL ON TABLES FROM PUBLIC, canteen_app_grp, canteen_readonly_grp;
ALTER DEFAULT PRIVILEGES FOR ROLE canteen_admin IN SCHEMA public
    REVOKE ALL ON SEQUENCES FROM PUBLIC, canteen_app_grp, canteen_readonly_grp;

ALTER DEFAULT PRIVILEGES FOR ROLE canteen_admin
    REVOKE ALL ON TABLES FROM PUBLIC, canteen_app_grp, canteen_readonly_grp;
ALTER DEFAULT PRIVILEGES FOR ROLE canteen_admin
    REVOKE ALL ON SEQUENCES FROM PUBLIC, canteen_app_grp, canteen_readonly_grp;

ALTER DEFAULT PRIVILEGES FOR ROLE canteen_admin IN SCHEMA public
    GRANT SELECT, INSERT, UPDATE ON TABLES TO canteen_app_grp;
ALTER DEFAULT PRIVILEGES FOR ROLE canteen_admin IN SCHEMA public
    GRANT USAGE, SELECT ON SEQUENCES TO canteen_app_grp;

-- Read-only access is granted explicitly per approved table/column in script 04.

GRANT USAGE,CREATE ON SCHEMA public TO canteen_admin; SET ROLE canteen_admin; CREATE TABLE public.g05_upstream_probe(id int); RESET ROLE; SELECT has_table_privilege('canteen_app','public.g05_upstream_probe','SELECT') AS runtime_select, has_table_privilege('canteen_app','public.g05_upstream_probe','INSERT') AS runtime_insert, has_table_privilege('canteen_app','public.g05_upstream_probe','UPDATE') AS runtime_update; ROLLBACK;

SELECT version(),current_database();
SELECT rolname,rolcanlogin,rolsuper,rolcreatedb,rolcreaterole,rolreplication,rolbypassrls,rolinherit FROM pg_roles WHERE rolname LIKE 'canteen_%' ORDER BY rolname;
SELECT member.rolname AS member,parent.rolname AS parent,m.admin_option,m.inherit_option,m.set_option FROM pg_auth_members m JOIN pg_roles member ON member.oid=m.member JOIN pg_roles parent ON parent.oid=m.roleid WHERE member.rolname LIKE 'canteen_%' ORDER BY 1;
SELECT datname,pg_get_userbyid(datdba) AS owner,datacl FROM pg_database ORDER BY datname;
SELECT nspname,pg_get_userbyid(nspowner) AS owner,nspacl FROM pg_namespace WHERE nspname='public';
SELECT c.relname,c.relkind,pg_get_userbyid(c.relowner) AS owner,c.relacl FROM pg_class c JOIN pg_namespace n ON c.relnamespace=n.oid WHERE n.nspname='public' AND c.relkind IN ('r','S','v','m') ORDER BY c.relname;
SELECT table_name,column_name,privilege_type,grantee FROM information_schema.column_privileges WHERE grantee='canteen_readonly_grp' ORDER BY table_name,column_name;
SELECT conrelid::regclass,conname,pg_get_constraintdef(oid) FROM pg_constraint WHERE connamespace='public'::regnamespace ORDER BY 1,2;
SELECT defaclrole::regrole,defaclnamespace,defaclobjtype,defaclacl FROM pg_default_acl;
SELECT count(*) AS application_functions FROM pg_proc WHERE pronamespace='public'::regnamespace;
SELECT count(*) AS application_triggers FROM pg_trigger WHERE NOT tgisinternal;
SELECT 'student',count(*) FROM student UNION ALL SELECT 'vendor',count(*) FROM vendor UNION ALL SELECT 'menu_item',count(*) FROM menu_item UNION ALL SELECT 'customer_order',count(*) FROM customer_order UNION ALL SELECT 'order_item',count(*) FROM order_item UNION ALL SELECT 'queue_entry',count(*) FROM queue_entry UNION ALL SELECT 'notification',count(*) FROM notification;
SELECT count(*) AS probe_students FROM student WHERE email LIKE 'g05-%@example.invalid';
SELECT to_regclass('g05_future_probe') IS NULL AS future_table_removed, to_regprocedure('g05_future_function()') IS NULL AS future_function_removed;
